def largest_divisor(n: int) -> int:
    """ For a given number n, find the largest number that divides n evenly, smaller than n
    >>> largest_divisor(15)
    5
    """
    if n <= 1:
        return 1  # The only divisor smaller than n is 1 for n <= 1
    for i in range(n // 2, 0, -1):
        if n % i == 0:
            return i
    return 1  # Fallback, though logic should always find a divisor before this
