def correct_bracketing(brackets: str) -> bool:
    stack = []
    for char in brackets:
        if char == '<':
            stack.append(char)
        elif char == '>':
            if not stack:
                return False
            stack.pop()
        else:
            raise ValueError("Input contains invalid characters; only '<' and '>' are allowed.")
    return not stack
