def count_nums(arr):
    def digit_sum(n):
        if n == 0:
            return 0
        sign = -1 if n < 0 else 1
        n_abs = abs(n)
        total = 0
        while n_abs > 0:
            digit = n_abs % 10
            total += digit
            n_abs //= 10
        return sign * total

    count = 0
    for num in arr:
        if digit_sum(num) > 0:
            count += 1
    return count
