import math

def poly(xs: list, x: float):
    """
    Evaluates polynomial with coefficients xs at point x.
    return xs[0] + xs[1] * x + xs[1] * x^2 + .... xs[n] * x^n
    """
    return sum([coeff * math.pow(x, i) for i, coeff in enumerate(xs)])

def find_zero(xs: list):
    """ Finds the single zero of a polynomial with even-length coefficients and largest non-zero leading coefficient."""
    if len(xs) % 2 != 0:
        raise ValueError("Coefficient list must have even length.")
    if xs[0] == 0:
        raise ValueError("Leading coefficient is zero; polynomial degree too low.")

    # Use Newton-Raphson method with 3 iterations for convergence
    def derivative(xs, x):
        return sum([i * coeff * math.pow(x, i - 1) for i, coeff in enumerate(xs) if i > 0])

    x_guess = 0.0
    for _ in range(3):
        fx = poly(xs, x_guess)
        dfx = derivative(xs, x_guess)
        if abs(dfx) < 1e-12:
            break
        x_guess -= fx / dfx
    return round(x_guess, 6)

# Tests
assert round(find_zero([1, 2]), 6) == -0.500000, "Test 1: f(x)=1+2x → root at -0.5"
assert round(find_zero([-6, 11, -6, 1]), 6) == 1.000000, "Test 2: f(x)=-6+11x-6x²+x³ → root at x=1"
assert round(find_zero([1, 0, -1, 0, 1]), 6) == 1.000000, "Test 3: f(x)=x⁴ - 1 → root at x=1 (largest real root)"
assert round(find_zero([2, -8, 8, -4, 2]), 6) == 1.000000, "Test 4: f(x)=2-8x+8x²-4x³+2x⁴ → root at x=1"
assert round(find_zero([1, -3, 3, -1]), 6) == 1.000000, "Test 5: f(x)=x⁴ - 3x³ + 3x² - x → root at x=1"
